// Verifica la firma HMAC de KAWSAY (anti-manipulación y anti-replay). Secreto en variable de entorno de n8n.
const crypto = require('crypto');
const secret = $env.KAWSAY_WEBHOOK_SECRET;
const item = $input.first();
const raw = item.binary && item.binary.data ? Buffer.from(item.binary.data.data, 'base64').toString('utf8') : JSON.stringify(item.json.body);
const ts = item.json.headers['x-kawsay-timestamp'];
const sig = item.json.headers['x-kawsay-signature'] || '';
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.${raw}`).digest('hex');
const fresh = Math.abs(Date.now() / 1000 - Number(ts)) < 300;
const ok = fresh && sig.length === expected.length && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
return [{ json: { valid: ok, event: ok ? JSON.parse(raw) : null } }];

// Mensaje SIN nombres de estudiantes (minimización de datos). El docente abre KAWSAY para ver la evidencia.
const e = $json.event;
return [{ json: { teacher_ids: e.payload.teacher_ids, text: 'KAWSAY: hay una nueva alerta educativa en tu aula. Ingresa al panel para ver la evidencia y decidir cómo acompañar.', flag_id: e.payload.flag_id } }];
